"""The header of a generated file (the rendered briefs since T-0206, the protocol's README.md and WORKER_BRIEF.md since
T-0219): one blockquote line that names the sources as the only places to edit and ends with `Body sha256 <16 hex>`, the
digest of the text below it (the pattern of tickets/ticket.env's `generated-from ... sha256` line), then a blank line.

A renderer decides per existing file from that line: one that is word for word the header it would write now, for these
sources, and whose digest matches the body, marks an untouched generated file, so a changed template, notes, docs or config
renders straight through; a missing, reworded or garbled header, one naming other sources, or a body that no longer
matches is a hand edit, refused until it is folded back into a source, and `--force` is for that case only. A hand edit
that also recomputes the digest passes: the header guards against a hand edit made by accident, which is accepted.
"""
from __future__ import annotations

import hashlib

DIGEST_LEN = 16
LINE = ("> Generated by `{tool}` from {sources}. Do not edit this file: edit {those} and render again. "
        "Render refuses a hand-edited {noun}; `--force` only after the edit is folded back into a source. Body sha256 {digest}.")


def body_digest(body: str) -> str:
    return hashlib.sha256(body.encode("utf-8")).hexdigest()[:DIGEST_LEN]


def header_line(tool: str, sources: str, noun: str, those: str, digest: str) -> str:
    """The one line: `tool` is the command that renders the file, `sources` the markdown list of its inputs, `noun` what
    the file is called in the refusal ("brief", "file"), `those` how the sources are referred back to ("one of those two")."""
    return LINE.format(tool=tool, sources=sources, noun=noun, those=those, digest=digest)


def header(tool: str, sources: str, noun: str, those: str, body: str) -> str:
    """The header line for `body` and the blank line after it: prepend it to `body`."""
    return header_line(tool, sources, noun, those, body_digest(body)) + "\n\n"


def untouched(text: str, tool: str, sources: str, noun: str, those: str) -> bool:
    """True when `text` is a file this renderer wrote for exactly these sources and nobody edited it: its first line is,
    word for word, the header for its own body, and a blank line follows."""
    nl = text.find("\n")
    if nl < 0 or not text.startswith("> ") or text[nl + 1:nl + 2] != "\n":
        return False
    body = text[nl + 2:]
    return text[:nl] == header_line(tool, sources, noun, those, body_digest(body))
